import os
import shutil
import zipfile

from fastapi import FastAPI, Request, UploadFile, File, HTTPException
from fastapi.responses import HTMLResponse
from fastapi.staticfiles import StaticFiles
from starlette.templating import Jinja2Templates

app = FastAPI()

app.mount("/static", StaticFiles(directory="static"), name="static")
templates = Jinja2Templates(directory="templates")
templates.env.cache = {}

# ✅ Use /tmp — completely avoids the corrupt data/raw file
RAW_DIR = "/tmp/devdocs/raw"
EXTRACT_DIR = "/tmp/devdocs/extracted"


@app.get("/", response_class=HTMLResponse)
async def home(request: Request):
    return templates.TemplateResponse(
        "index.html",
        context={"request": request}
    )


@app.post("/upload")
async def upload_file(file: UploadFile = File(...)):
    if not file.filename.endswith(".zip"):
        raise HTTPException(status_code=400, detail="Only .zip files are supported")

    # Clean old extracted data
    if os.path.exists(EXTRACT_DIR):
        shutil.rmtree(EXTRACT_DIR)

    os.makedirs(EXTRACT_DIR, exist_ok=True)
    os.makedirs(RAW_DIR, exist_ok=True)

    zip_path = os.path.join(RAW_DIR, file.filename)
    with open(zip_path, "wb") as buffer:
        shutil.copyfileobj(file.file, buffer)

    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(EXTRACT_DIR)
    except zipfile.BadZipFile:
        raise HTTPException(status_code=400, detail="Invalid ZIP file")

    return {"message": "Upload successful. Codebase extracted."}


@app.post("/ask")
async def ask_question(data: dict):
    question = data.get("question")
    if not question:
        raise HTTPException(status_code=400, detail="Question is required")
    return {"answer": f"You asked: {question}"}

/* Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', sans-serif;
    background: #0b1220;
    color: #e5e7eb;
}

/* App Container */
.app {
    max-width: 900px;
    margin: 50px auto;
    padding: 20px;
}

/* Header */
.header {
    text-align: center;
    margin-bottom: 40px;
}

.header h1 {
    font-size: 32px;
    font-weight: 600;
}

.header p {
    color: #9ca3af;
    margin-top: 8px;
}

/* Grid Layout */
.grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

/* Cards */
.card {
    background: #111827;
    padding: 20px;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.3);
}

.full-width {
    grid-column: span 2;
}

/* Titles */
.card h2 {
    margin-bottom: 15px;
    font-size: 18px;
}

/* Inputs */
input[type="file"],
input[type="text"] {
    width: 100%;
    padding: 10px;
    margin-bottom: 12px;
    border-radius: 8px;
    border: 1px solid #374151;
    background: #020617;
    color: white;
}

/* Buttons */
.primary-btn {
    width: 100%;
    padding: 10px;
    border: none;
    border-radius: 8px;
    background: #2563eb;
    color: white;
    font-weight: 500;
    cursor: pointer;
    transition: 0.2s;
}

.primary-btn:hover {
    background: #1d4ed8;
}

/* Status text */
.status {
    margin-top: 10px;
    color: #9ca3af;
}

/* Answer box */
.answer-box {
    background: #020617;
    padding: 15px;
    border-radius: 8px;
    min-height: 80px;
    line-height: 1.5;
    border: 1px solid #374151;
}
